import{_ as e}from"./chunks/轴体对比.Bg90VzsT.js";import{_ as s}from"./chunks/轴体对比2.4HahvOUz.js";import{_ as r,c as a,o as l,a0 as o}from"./chunks/framework._Jgw3yL-.js";const x=JSON.parse('{"title":"高軸 vs. 矮軸","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/基础定制/轴体选择.md","filePath":"zh-HK/基础定制/轴体选择.md"}'),i={name:"zh-HK/基础定制/轴体选择.md"};function n(d,t,g,m,c,_){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="高軸-vs-矮軸" tabindex="-1">高軸 vs. 矮軸 <a class="header-anchor" href="#高軸-vs-矮軸" aria-label="Permalink to &quot;高軸 vs. 矮軸&quot;">​</a></h1><p>由於軸座不同，所以高軸和矮軸的PCB電路板不能通用！</p><div class="image-row image-row-2"><div class="image-item"><img src="'+e+'" alt="键帽1" class="zoom-small"><div>軸體</div></div><div class="image-item"><img src="'+s+'" alt="键帽2" class="zoom-small"><div>鍵帽</div></div></div><div class="image-row image-row-2"><div class="image-item"><img src="'+e+'" alt="键帽1" class="zoom-small"><div>軸座</div></div><div class="image-item"><img src="'+s+'" alt="键帽2" class="zoom-small"><div>键帽</div></div></div><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">組件</th><th style="text-align:left;">高軸 (常規軸體)</th><th style="text-align:left;">矮軸 (Low-Profile)</th><th style="text-align:left;">影響與分析</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>定位板厚度</strong></td><td style="text-align:left;"><strong>較厚</strong><br>（通常為1.5mm）</td><td style="text-align:left;"><strong>較薄</strong><br>（不超過1.2mm）</td><td style="text-align:left;"><strong>影響</strong>：矮軸體本身的高度大幅降低，為了維持整體的低平外觀，定位板也必須做得更薄。<br><strong>分析</strong>：更薄的定位板可能會輕微影響整體的剛性，但在追求“軟彈”手感的Gasket結構鍵盤中，這種差異有時會被利用來增強形變。</td></tr><tr><td style="text-align:left;"><strong>軸座設計</strong></td><td style="text-align:left;"><strong>標準尺寸</strong><br>（Cherry MX規格）</td><td style="text-align:left;"><strong>重新設計，更為緊湊</strong></td><td style="text-align:left;"><strong>影響</strong>：矮軸的引腳（金屬針腳和塑料支柱）更短，間距也可能不同，導致其<strong>與高軸不兼容</strong>。<br><strong>分析</strong>：PCB上的軸座（軸體插座）必須為矮軸的特殊引腳布局進行重新設計和布局，其本身的物理尺寸也變得更小、更扁平，以適應更薄的總體空間。</td></tr><tr><td style="text-align:left;"><strong>PCB厚度</strong></td><td style="text-align:left;"><strong>標準厚度</strong><br>（通常為1.6mm）</td><td style="text-align:left;"><strong>基本相同或略微變薄</strong></td><td style="text-align:left;"><strong>影響</strong>：PCB的厚度主要由電路層數和機械強度要求決定，與使用高軸或矮軸關係不大。<br><strong>分析</strong>：雖然整體空間被壓縮，但PCB仍需保證基本的電氣性能和結構強度，因此其厚度通常是最後才被考慮減薄的環節，變化不大。</td></tr></tbody></table>',6)])])}const y=r(i,[["render",n]]);export{x as __pageData,y as default};
